const { email, pseudo, articles } = $input.first().json;
const list = (Array.isArray(articles) ? articles : []).filter(a => a && a.title && /^https?:\/\//i.test(String(a.url ?? '')));

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const safeUrl = u => /^https?:\/\//i.test(String(u)) ? String(u) : '#';

const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'Europe/Paris' });
const hello = pseudo ? `Bonjour ${pseudo},` : 'Bonjour,';
const subject = `Ta newsletter Persona du ${date}`;

const intro = list.length
  ? `Voici ${list.length} article${list.length > 1 ? 's' : ''} choisi${list.length > 1 ? 's' : ''} selon tes centres d'intérêt.`
  : "Pas de nouvel article sur tes centres d'intérêt aujourd'hui. À demain !";

const footerText = "Tu reçois cet email parce que tu es inscrit(e) à Persona. Pour te désabonner, réponds « désabonne-moi » à Persona dans le chat. Persona conserve uniquement ton email, tes centres d'intérêt et ton horaire d'envoi, pour t'envoyer cette newsletter. Pour supprimer toutes tes données, réponds « supprime mes données » dans le chat.";

const cards = list.map(a => `
  <tr><td style="padding:16px 0;border-bottom:1px solid #e5e5e5;">
    <a href="${esc(safeUrl(a.url))}" style="font-size:18px;font-weight:bold;color:#1a1a1a;text-decoration:none;line-height:1.3;">${esc(a.title)}</a>
    ${a.source ? `<div style="font-size:13px;color:#888;margin-top:4px;">${esc(a.source)}</div>` : ''}
    ${a.summary ? `<p style="font-size:15px;color:#333;line-height:1.5;margin:8px 0;">${esc(a.summary)}</p>` : ''}
    <a href="${esc(safeUrl(a.url))}" style="font-size:14px;color:#5b4bdb;">Lire l'article →</a>
  </td></tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f4f4f7;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f7;"><tr><td align="center" style="padding:24px 12px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px;">
    <tr><td style="padding:24px 24px 8px;">
      <div style="font-size:24px;font-weight:bold;color:#5b4bdb;">Persona</div>
      <p style="font-size:16px;color:#1a1a1a;margin:16px 0 4px;">${esc(hello)}</p>
      <p style="font-size:15px;color:#333;margin:0;">${esc(intro)}</p>
    </td></tr>
    <tr><td style="padding:0 24px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${cards}</table></td></tr>
    <tr><td style="padding:24px;font-size:12px;color:#888;line-height:1.5;">${esc(footerText)}</td></tr>
  </table>
</td></tr></table>
</body></html>`;

const text = [
  hello, '', intro, '',
  ...list.flatMap((a, i) => [`${i + 1}. ${a.title}${a.source ? ` (${a.source})` : ''}`, ...(a.summary ? [a.summary] : []), a.url, '']),
  '---', footerText
].join('\n');

return [{ json: { email, subject, html, text, nb_articles: list.length, article_ids: list.map(a => a.id) } }];
